import subprocess, sys, pathlib
root = pathlib.Path(sys.argv[1]); py = sys.argv[2]
M = {
 "M1_drop_pdf_label": ("app/reports/pdf.py", 'flow.append(Paragraph(f"<b>{report[\'seeded_label\']}</b>", styles["Lede"]))', 'pass'),
 "M2_drop_reconciliation_line": ("app/reports/pdf.py", 'f"Generated by {report.get(\'generated_by\') or \'system\'} at {generated}<br/>"', 'f"Generated by {report.get(\'generated_by\') or \'system\'} at {generated}"\n        ""'),
 "M2b_drop_reconciliation_timestamp": ("app/reports/pdf.py", 'f"Figures reconciled with the Command Center at generation, {generated}."', 'f"Figures reconciled with the Command Center at generation, ."'),
 "M3_seed_figures_as_of_eq_business_date": ("app/services/report_service.py", "figures_as_of=today()))", "figures_as_of=on))"),
 "M4_label_every_report": ("app/schemas/governance.py", "        if not self.is_seeded:\n            return None\n", ""),
 "M5_generate_figures_as_of_none": ("app/services/report_service.py", "figures_as_of=on,  # D14", "figures_as_of=None,  # D14"),
 "M6_null_fallback_wrong": ("app/schemas/governance.py", 'if self.figures_as_of else ""', 'if self.figures_as_of else f" on {self.business_date.isoformat()}"'),
 "M7_seed_label_omits_business_date": ("app/schemas/governance.py", 'f"dated {self.business_date.isoformat()} for illustration.")', 'f"dated earlier for illustration.")'),
 "M8_seed_rederives_from_offset_wrong": ("app/services/report_service.py", "figures_as_of=today()))", "figures_as_of=on + timedelta(days=SEED_REPORT_AGE_DAYS - 1)))"),
}
names = sys.argv[3:] or list(M)
for name in names:
    rel, old, new = M[name]
    p = root / rel; src = p.read_text(encoding="utf-8")
    assert src.count(old) == 1, (name, src.count(old))
    p.write_text(src.replace(old, new), encoding="utf-8")
    try:
        r = subprocess.run([py, "-m", "pytest", "-q", "-p", "no:cacheprovider", "tests/test_reports.py", "tests/test_db_config.py"],
                           cwd=root, capture_output=True, text=True)
        tail = [l for l in r.stdout.splitlines() if l.startswith("FAILED") or " passed" in l or " failed" in l]
        print(f"== {name}: {'KILLED' if r.returncode else 'SURVIVED'}"); print("\n".join(tail[-12:]), flush=True)
    finally:
        p.write_text(src, encoding="utf-8")
